arguments.command:
ls -la && echo "---" && python3 -I -c "
import json
d=json.load(open('/app/measurements.json'))
def show(x,ind=0,key=''):
    pad=' '*ind
    if isinstance(x,dict):
        print(pad+key+' {')
        for k,v in x.items(): show(v,ind+2,k)
        print(pad+'}')
    elif isinstance(x,list):
        if len(x)>0 and all(isinstance(e,(int,float)) for e in x):
            print(pad+key+f' list[{len(x)}] floats: first {x[:4]} ... last {x[-3:]}')
        else:
            print(pad+key+f' list[{len(x)}]')
            for i,e in enumerate(x[:50]): show(e,ind+2,f'[{i}]')
    else:
        print(pad+key+' = '+repr(x))
show(d)
"

